# IAM policy that grants only read access to one bucket, nothing more
{
  "Effect": "Allow",
  "Action": ["s3:GetObject", "s3:ListBucket"],
  "Resource": ["arn:aws:s3:::app-assets", "arn:aws:s3:::app-assets/*"]
}

# Excerpt of a SLSA v1 provenance attestation (in-toto statement)
{
  "predicateType": "https://slsa.dev/provenance/v1",
  "predicate": {
    "buildDefinition": {"externalParameters": {"source": "git+https://github.com/acme/app@refs/tags/v1.4.2"}},
    "runDetails": {"builder": {"id": "https://github.com/actions/runner"}}
  }
}

# Enforce ownership on every request, not just in the UI
@app.get("/orders/{order_id}")
def get_order(order_id, user=Depends(current_user)):
    order = db.get(Order, order_id)
    if order.owner_id != user.id:
        raise HTTPException(403)   # prevents IDOR / broken access control
    return order

# Map controls to frameworks in a compliance-as-code check (e.g. Terraform + OPA)
deny[msg] {
  input.resource_type == "aws_s3_bucket"
  not input.server_side_encryption
  msg := sprintf("%s: encryption at rest required (PCI DSS 3.4, SOC 2 CC6.1)", [input.name])
}

# A JWT is header.payload.signature, each part base64url-encoded
JWT='eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJzdWIiOiJhbGljZSIsImV4cCI6MTc1MDAwMDAwMH0.sig...'
echo "$JWT" | cut -d. -f1 | base64 -d 2>/dev/null   # {"alg":"HS256","typ":"JWT"}
echo "$JWT" | cut -d. -f2 | base64 -d 2>/dev/null   # {"sub":"alice","exp":1750000000}

# Server opts in to a specific trusted origin (nginx)
add_header Access-Control-Allow-Origin "https://app.example.com";
add_header Access-Control-Allow-Methods "GET, POST, OPTIONS";
add_header Access-Control-Allow-Headers "Authorization, Content-Type";
# Browser preflight: OPTIONS /api/orders  Origin: https://app.example.com

# Baseline security headers in nginx
add_header Content-Security-Policy "default-src 'self'; object-src 'none'" always;
add_header Strict-Transport-Security "max-age=31536000; includeSubDomains" always;
add_header X-Content-Type-Options "nosniff" always;
add_header Referrer-Policy "strict-origin-when-cross-origin" always;

# Gatekeeper (OPA) constraint: every pod image must come from the internal registry
apiVersion: constraints.gatekeeper.sh/v1beta1
kind: K8sAllowedRepos
metadata: {name: internal-registry-only}
spec:
  match: {kinds: [{apiGroups: [""], kinds: ["Pod"]}]}
  parameters: {repos: ["registry.acme.internal/"]}
